viewport.css:
* { box-sizing: border-box; }
body { margin: 0; padding: 20px; font-family: Arial, sans-serif; background: #101827; color: white; }
.container { width: 100%; max-width: 900px; margin: auto; }
header { padding: 35px 20px; text-align: center; background: #087f9b; border-radius: 14px; }
header h1 { font-size: clamp(24px, 5vw, 42px); }
.content { margin-top: 20px; padding: 25px; background: #1d2b42; border-radius: 14px; }
.features { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 20px; }
.features article { flex: 1 1 150px; padding: 20px; text-align: center; background: #087f9b; border-radius: 10px; }
img { max-width: 100%; height: auto; }

grid.css:
* { box-sizing: border-box; }
body { margin: 0; padding: 25px; font-family: Arial, sans-serif; background: #101827; color: white; }
.container { max-width: 1000px; margin: auto; }
.grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 15px; margin-top: 25px; }
article { min-height: 160px; display: grid; place-content: center; text-align: center; padding: 20px; background: linear-gradient(135deg, #087f8c, #344e9b); border-radius: 14px; }
article h2 { font-size: 35px; margin: 0; }
article p { margin-bottom: 0; }

media.css:
* { box-sizing: border-box; }
body { margin: 0; padding: 25px; font-family: Arial, sans-serif; background: #17213c; color: white; }
.container { max-width: 1000px; margin: auto; }
.cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; margin-top: 25px; }
.cards article { padding: 35px 15px; text-align: center; background: #087f9b; border-radius: 14px; }
.cards h2 { font-size: 35px; }
@media (max-width: 700px) { .cards { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 430px) { .cards { grid-template-columns: 1fr; } }

images.css:
* { box-sizing: border-box; }
body { margin: 0; padding: 20px; font-family: Arial, sans-serif; background: #101827; color: white; }
.container { max-width: 850px; margin: auto; }
figure { margin: 20px 0; }
figure img { display: block; width: 100%; height: auto; border-radius: 14px; }
figcaption { padding: 10px 0; color: #b9c5d8; }
.gallery { display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px; }
.gallery img { width: 100%; height: 200px; object-fit: cover; border-radius: 12px; }
@media (max-width: 500px) { .gallery { grid-template-columns: 1fr; } .gallery img { height: auto; } }

videos.css:
* { box-sizing: border-box; }
body { margin: 0; padding: 20px; font-family: Arial, sans-serif; background: #101827; color: white; }
.container { max-width: 850px; margin: auto; }
.video-card { margin-top: 25px; padding: 20px; background: #1d2b42; border-radius: 14px; }
video { display: block; width: 100%; height: auto; border-radius: 12px; background: black; }
.video-card h2 { color: #37c9e8; }
.video-card p { line-height: 1.7; color: #cbd5e1; }

frameworks.css:
* { box-sizing: border-box; }
body { margin: 0; padding: 20px; font-family: Arial, sans-serif; background: #101827; color: white; }
.container { max-width: 1000px; margin: auto; }
header { padding: 25px; text-align: center; background: #172c48; border-radius: 12px; }
.row { display: grid; grid-template-columns: repeat(3, 1fr); gap: 15px; margin-top: 20px; }
article { padding: 25px 15px; background: #087f9b; border-radius: 12px; }
article p { line-height: 1.6; }
@media (max-width: 750px) { .row { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 480px) { .row { grid-template-columns: 1fr; } }

templates.css:
* { box-sizing: border-box; }
body { margin: 0; padding: 20px; font-family: Arial, sans-serif; background: #101827; color: white; }
.page { max-width: 1000px; margin: auto; }
header { padding: 25px; background: #172c48; border-radius: 12px; }
nav { display: flex; flex-wrap: wrap; gap: 20px; margin-top: 15px; }
nav a { color: #55d9f2; text-decoration: none; }
.hero { margin-top: 18px; padding: 45px 25px; text-align: center; background: linear-gradient(135deg, #087f9b, #344e9b); border-radius: 12px; }
.hero button { padding: 12px 22px; border: none; border-radius: 8px; background: white; color: #172c48; cursor: pointer; }
.about { margin-top: 18px; padding: 25px; background: #1d2b42; border-radius: 12px; }
.cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 15px; margin-top: 18px; }
.cards article { padding: 22px; background: #087f9b; border-radius: 12px; }
footer { margin-top: 18px; padding: 20px; text-align: center; background: #172c48; border-radius: 12px; color: #b9c5d8; }
@media (max-width: 650px) { .cards { grid-template-columns: 1fr; } nav { gap: 12px; } .hero { padding: 30px 15px; } }
